from xml.etree import ElementTree as ETimport pytestfrom src.editor_core.codec import (    _coerce_scalar,    _element_to_value,    project_from_json,    project_from_xml,    project_to_json,    project_to_xml,)from src.editor_core.project import Asset, Clip, Project, Timeline, Trackdef _sample_project() -> Project:    return Project(        id="project-1",        name="Codec Test",        assets=[            Asset(                id="asset-1",                path="/tmp/video.mp4",                media_type="video",                metadata={"rating": 5},            )        ],        timeline=Timeline(            duration=5.0,            tracks=[                Track(                    id="track-1",                    kind="video",                    clips=[Clip(id="clip-1", asset_id="asset-1", start=0.0, end=2.0)],                )            ],        ),        metadata={"published": True},    )def test_coerce_scalar_parses_primitive_values():    assert _coerce_scalar("  ") == ""    assert _coerce_scalar("true") is True    assert _coerce_scalar("FALSE") is False    assert _coerce_scalar("12") == 12    assert _coerce_scalar("12.5") == 12.5    assert _coerce_scalar("hello") == "hello"def test_element_to_value_preserves_empty_list_and_dict():    list_node = ET.Element("items", {"data-kind": "list"})    dict_node = ET.Element("meta", {"data-kind": "dict"})    assert _element_to_value(list_node) == []    assert _element_to_value(dict_node) == {}def test_project_json_roundtrip():    original = _sample_project()    text = project_to_json(original)    restored = project_from_json(text)    assert restored.id == original.id    assert restored.assets[0].metadata["rating"] == 5    assert restored.timeline.tracks[0].clips[0].id == "clip-1"def test_project_xml_roundtrip():    original = _sample_project()    xml_text = project_to_xml(original)    restored = project_from_xml(xml_text)    assert restored.id == original.id    assert restored.metadata["published"] is True    assert restored.timeline.tracks[0].clips[0].asset_id == "asset-1"def test_project_from_xml_raises_when_root_is_not_mapping():    with pytest.raises(ValueError):        project_from_xml("<project>1</project>")